import React, { useEffect, useState } from "react";
import logo from "../assests/vighnexlogo.png";

export default function Home() {
  const [menuOpen, setMenuOpen] = useState(false);
  const [activeFaq, setActiveFaq] = useState(0);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 40);
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  const scrollTo = (id) => {
    setMenuOpen(false);
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
  };

  const Icon = ({ type, size = 26 }) => {
    const icons = {
      code: (
        <>
          <path d="M9 18 3 12l6-6" />
          <path d="m15 6 6 6-6 6" />
          <path d="m14 4-4 16" />
        </>
      ),
      design: (
        <>
          <rect x="3" y="3" width="18" height="18" rx="3" />
          <path d="M8 8h8M8 12h5M8 16h8" />
        </>
      ),
      marketing: (
        <>
          <path d="M3 11v2" />
          <path d="M6 9v6" />
          <path d="M9 7v10" />
          <path d="M12 5v14" />
          <path d="M15 8v8" />
          <path d="M18 10v4" />
          <path d="M21 12h.01" />
        </>
      ),
      mobile: (
        <>
          <rect x="6" y="2" width="12" height="20" rx="3" />
          <path d="M10 18h4" />
        </>
      ),
      cloud: (
        <path d="M17.5 19H9a6 6 0 1 1 1.3-11.86A7 7 0 0 1 23 12a4 4 0 0 1-5.5 7Z" />
      ),
      shield: (
        <>
          <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z" />
          <path d="m9 12 2 2 4-5" />
        </>
      ),
      rocket: (
        <>
          <path d="M4.5 16.5c-1.5 1.5-2 4-2 4s2.5-.5 4-2l2-2-2-2-2 2Z" />
          <path d="m14 5 5 5" />
          <path d="M13 4c3-2 7-2 8-1-1 1 0 5-1 7l-7 7-5-5 7-8Z" />
          <circle cx="16" cy="8" r="1" />
        </>
      ),
      target: (
        <>
          <circle cx="12" cy="12" r="9" />
          <circle cx="12" cy="12" r="5" />
          <circle cx="12" cy="12" r="1" />
        </>
      ),
      users: (
        <>
          <path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2" />
          <circle cx="9" cy="7" r="4" />
          <path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75" />
        </>
      ),
      arrow: (
        <>
          <path d="M5 12h14" />
          <path d="m13 6 6 6-6 6" />
        </>
      ),
      star: (
        <path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-2.9-5.6 2.9 1.1-6.2L3 9.6l6.2-.9L12 3Z" />
      ),
      phone: (
        <path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.8 19.8 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.12 4.2 2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.12.9.33 1.78.62 2.63a2 2 0 0 1-.45 2.11L8 9.73a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45c.85.29 1.73.5 2.63.62A2 2 0 0 1 22 16.92Z" />
      ),
      mail: (
        <>
          <rect x="3" y="5" width="18" height="14" rx="2" />
          <path d="m3 7 9 6 9-6" />
        </>
      ),
      location: (
        <>
          <path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0Z" />
          <circle cx="12" cy="10" r="2.5" />
        </>
      ),
      menu: <path d="M4 6h16M4 12h16M4 18h16" />,
      close: (
        <>
          <path d="M6 6l12 12" />
          <path d="M18 6 6 18" />
        </>
      ),
      spark: (
        <>
          <path d="m12 3 1.5 5.5L19 10l-5.5 1.5L12 17l-1.5-5.5L5 10l5.5-1.5L12 3Z" />
          <path d="m19 16 .7 2.3L22 19l-2.3.7L19 22l-.7-2.3L16 19l2.3-.7L19 16Z" />
        </>
      ),
      layers: (
        <>
          <path d="m12 2 9 5-9 5-9-5 9-5Z" />
          <path d="m3 12 9 5 9-5" />
          <path d="m3 17 9 5 9-5" />
        </>
      ),
    };

    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.8"
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        {icons[type] || icons.spark}
      </svg>
    );
  };

  const services = [
    {
      icon: "code",
      title: "Web Development",
      text: "High-performance websites and web platforms engineered for speed, accessibility, scalability and measurable business growth.",
      tags: ["React", "Next.js", "Node.js"],
    },
    {
      icon: "design",
      title: "UI/UX Design",
      text: "Human-centered digital experiences combining research, visual systems, interaction design and conversion-focused interfaces.",
      tags: ["Figma", "Design Systems", "Prototyping"],
    },
    {
      icon: "marketing",
      title: "Digital Marketing",
      text: "Data-led marketing strategies that increase visibility, attract qualified audiences and turn attention into sustainable growth.",
      tags: ["SEO", "Social Media", "Analytics"],
    },
    {
      icon: "mobile",
      title: "Mobile Development",
      text: "Modern Android and iOS applications with intuitive interfaces, secure architecture and reliable performance.",
      tags: ["Android", "iOS", "Cross Platform"],
    },
    {
      icon: "cloud",
      title: "Cloud Development",
      text: "Secure cloud-native solutions designed for resilience, automation, cost efficiency and effortless scaling.",
      tags: ["AWS", "Azure", "DevOps"],
    },
  ];

  const technologies = [
    ["React", "Frontend"],
    ["Next.js", "Frontend"],
    ["Node.js", "Backend"],
    ["Python", "Backend"],
    ["Java", "Backend"],
    ["Flutter", "Mobile"],
    ["MongoDB", "Database"],
    ["PostgreSQL", "Database"],
    ["AWS", "Cloud"],
    ["Docker", "DevOps"],
    ["Figma", "Design"],
    ["GitHub", "Development"],
  ];

  const process = [
    ["01", "Discover", "We understand your goals, audience, challenges and opportunities before writing a single line of code.", "target"],
    ["02", "Strategize", "We convert business requirements into a clear digital roadmap with measurable priorities.", "layers"],
    ["03", "Design", "We create intuitive interfaces and experiences that feel natural, premium and purposeful.", "design"],
    ["04", "Build", "Our engineers transform the approved experience into secure, scalable and high-quality products.", "code"],
    ["05", "Launch", "We test, optimize, deploy and monitor your solution for a confident launch.", "rocket"],
    ["06", "Grow", "We continue improving your product using data, feedback, experiments and technology.", "spark"],
  ];

  const projects = [
    {
      title: "FinEdge",
      category: "FinTech Platform",
      text: "A modern financial management experience designed around clarity, trust and frictionless digital journeys.",
      image:
        "https://images.unsplash.com/photo-1556761175-b413da4baf72?auto=format&fit=crop&w=1200&q=85",
    },
    {
      title: "Medivista",
      category: "Healthcare Experience",
      text: "A patient-focused digital ecosystem that makes appointments, information and communication easier.",
      image:
        "https://images.unsplash.com/photo-1559757148-5c350d0d3c56?auto=format&fit=crop&w=1200&q=85",
    },
    {
      title: "UrbanCart",
      category: "E-Commerce",
      text: "A conversion-focused shopping experience built for speed, discovery and effortless checkout.",
      image:
        "https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?auto=format&fit=crop&w=1200&q=85",
    },
  ];

  const testimonials = [
    {
      name: "Ananya Rao",
      role: "Founder, Nova Ventures",
      text: "The Vighnex team understood our vision quickly and turned it into a digital experience that feels far more premium than we imagined.",
      image:
        "https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=300&q=80",
    },
    {
      name: "Rahul Mehta",
      role: "Director, Crest Solutions",
      text: "What impressed us most was the combination of design thinking and technical discipline. Communication was clear from start to finish.",
      image:
        "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=300&q=80",
    },
    {
      name: "Priya Sharma",
      role: "Entrepreneur",
      text: "They did not simply build a website. They helped us think through our entire digital presence and created something our customers love.",
      image:
        "https://images.unsplash.com/photo-1531123897727-8f129e1688ce?auto=format&fit=crop&w=300&q=80",
    },
  ];

  const faqs = [
    [
      "What services does Vighnex Technologies provide?",
      "We provide web development, UI/UX design, digital marketing, mobile application development and cloud development. We can also combine multiple services into one complete digital transformation engagement.",
    ],
    [
      "Can you build a website from an idea only?",
      "Yes. We can start from a concept, business requirement, rough sketch or existing website. We help define the structure, user journey, visual direction, technology and launch plan.",
    ],
    [
      "Do you develop mobile applications for both Android and iOS?",
      "Yes. Depending on project requirements, we can build native or cross-platform applications with a strong focus on performance, security and user experience.",
    ],
    [
      "Do you provide maintenance after launch?",
      "Yes. We can provide ongoing technical support, security updates, performance improvements, content changes, analytics and feature development.",
    ],
    [
      "How do you handle project communication?",
      "We maintain a structured communication process with requirement discussions, progress updates, reviews, testing and final deployment so clients always understand the current project status.",
    ],
    [
      "How can I start a project with Vighnex?",
      "Simply contact us with your idea, requirements or business challenge. We will understand your objectives and discuss the most practical next steps.",
    ],
  ];

  return (
    <div className="site">
      <style>{`
        *{
          box-sizing:border-box;
          margin:0;
          padding:0;
        }

        html{
          scroll-behavior:smooth;
        }

        body{
          font-family:Inter,Arial,sans-serif;
          color:#11243a;
          background:#faf7f0;
        }

        .site{
          overflow:hidden;
          background:#faf7f0;
        }

        :root{
          --navy:#092338;
          --navy2:#12344c;
          --gold:#c89032;
          --gold2:#e6b85c;
          --cream:#faf7f0;
          --white:#fff;
          --text:#11243a;
          --muted:#637181;
        }

        .container{
          width:min(1180px,92%);
          margin:auto;
        }

        .section{
          padding:105px 0;
          position:relative;
        }

        .section-dark{
          background:linear-gradient(135deg,#071f32,#0d354c);
          color:white;
        }

        .section-title{
          text-align:center;
          max-width:720px;
          margin:0 auto 60px;
        }

        .eyebrow{
          display:inline-flex;
          align-items:center;
          gap:10px;
          color:var(--gold);
          font-size:12px;
          letter-spacing:4px;
          font-weight:800;
          text-transform:uppercase;
          margin-bottom:14px;
        }

        .eyebrow:before,
        .eyebrow:after{
          content:"";
          height:1px;
          width:30px;
          background:currentColor;
        }

        .section-title h2{
          font-family:Georgia,serif;
          font-size:clamp(36px,5vw,58px);
          line-height:1.05;
          margin-bottom:18px;
          color:var(--navy);
        }

        .section-dark .section-title h2{
          color:white;
        }

        .section-title p{
          font-size:17px;
          line-height:1.8;
          color:var(--muted);
        }

        .section-dark .section-title p{
          color:#cbd8e0;
        }

        .btn{
          border:0;
          border-radius:50px;
          padding:15px 25px;
          font-size:14px;
          font-weight:800;
          cursor:pointer;
          display:inline-flex;
          align-items:center;
          justify-content:center;
          gap:10px;
          transition:.3s;
          text-decoration:none;
        }

        .btn-primary{
          background:var(--navy);
          color:white;
          box-shadow:0 12px 28px rgba(9,35,56,.18);
        }

        .btn-primary:hover{
          transform:translateY(-3px);
          background:#153e59;
        }

        .btn-gold{
          background:linear-gradient(135deg,var(--gold2),var(--gold));
          color:#152536;
        }

        .btn-gold:hover{
          transform:translateY(-3px);
          box-shadow:0 12px 30px rgba(200,144,50,.28);
        }

        .navbar{
          position:fixed;
          left:0;
          right:0;
          top:0;
          height:78px;
          z-index:1000;
          display:flex;
          align-items:center;
          transition:.3s;
          background:rgba(250,247,240,.92);
          backdrop-filter:blur(14px);
        }

        .navbar.scrolled{
          box-shadow:0 8px 30px rgba(0,0,0,.08);
        }

        .nav-inner{
          display:flex;
          align-items:center;
          justify-content:space-between;
        }

        .logo{
          display:flex;
          align-items:center;
          cursor:pointer;
          min-width:0;
          background:transparent;
        }

        .brand-logo{
          display:block;
          width:220px;
          height:70px;
          object-fit:contain;
          object-position:left center;
          background:transparent;
          border:0;
          border-radius:0;
          box-shadow:none;
          outline:none;
          padding:0;
          margin:0;
        }

        .footer .brand-logo{
          width:250px;
          height:82px;
        }

        .nav-links{
          display:flex;
          align-items:center;
          gap:32px;
        }

        .nav-links button{
          border:0;
          background:none;
          font-weight:700;
          color:#24384b;
          cursor:pointer;
          font-size:14px;
          position:relative;
          padding:7px 0;
        }

        .nav-links button:after{
          content:"";
          position:absolute;
          bottom:0;
          left:50%;
          width:0;
          height:2px;
          background:var(--gold);
          transition:.3s;
        }

        .nav-links button:hover:after{
          left:0;
          width:100%;
        }

        .menu-btn{
          display:none;
          background:none;
          border:0;
          color:var(--navy);
          cursor:pointer;
        }

        .hero{
          min-height:760px;
          padding-top:150px;
          padding-bottom:80px;
          position:relative;
          background:
            radial-gradient(circle at 78% 35%,rgba(214,169,78,.2),transparent 32%),
            linear-gradient(110deg,#faf7f0 40%,#f0e5ce);
        }

        .hero:before{
          content:"";
          position:absolute;
          width:600px;
          height:600px;
          border:1px solid rgba(200,144,50,.18);
          border-radius:50%;
          right:-200px;
          top:120px;
        }

        .hero:after{
          content:"";
          position:absolute;
          width:420px;
          height:420px;
          border:1px solid rgba(200,144,50,.15);
          border-radius:50%;
          right:-110px;
          top:210px;
        }

        .hero-grid{
          display:grid;
          grid-template-columns:1fr 1fr;
          gap:50px;
          align-items:center;
          position:relative;
          z-index:2;
        }

        .hero-copy .eyebrow{
          margin-bottom:22px;
        }

        .hero h1{
          font-family:Georgia,serif;
          font-size:clamp(48px,6.2vw,78px);
          line-height:.98;
          color:var(--navy);
          letter-spacing:-2px;
        }

        .hero h1 span{
          color:var(--gold);
        }

        .hero-copy>p{
          max-width:600px;
          font-size:18px;
          line-height:1.75;
          color:#566575;
          margin:27px 0 32px;
        }

        .hero-actions{
          display:flex;
          gap:14px;
          flex-wrap:wrap;
        }

        .hero-note{
          display:flex;
          align-items:center;
          gap:12px;
          margin-top:30px;
          color:#526274;
          font-size:13px;
        }

        .hero-note strong{
          color:var(--navy);
        }

        .hero-visual{
          position:relative;
          min-height:520px;
          display:flex;
          align-items:center;
          justify-content:center;
        }

        .hero-image{
          width:430px;
          height:500px;
          object-fit:cover;
          border-radius:220px 220px 30px 30px;
          box-shadow:25px 30px 70px rgba(29,45,58,.2);
          border:8px solid rgba(255,255,255,.75);
        }

        .hero-badge{
          position:absolute;
          background:white;
          padding:18px 20px;
          border-radius:18px;
          box-shadow:0 15px 40px rgba(20,40,55,.13);
          display:flex;
          gap:12px;
          align-items:center;
        }

        .hero-badge.one{
          left:0;
          top:100px;
        }

        .hero-badge.two{
          right:0;
          bottom:75px;
        }

        .badge-icon{
          width:43px;
          height:43px;
          border-radius:13px;
          background:#fff2d4;
          color:var(--gold);
          display:grid;
          place-items:center;
        }

        .badge-text strong{
          display:block;
          color:var(--navy);
          font-size:15px;
        }

        .badge-text span{
          font-size:11px;
          color:#7a8792;
        }

        .mandala{
          position:absolute;
          width:100px;
          height:100px;
          border:2px dashed rgba(200,144,50,.35);
          border-radius:50%;
          right:15px;
          top:25px;
        }

        .about-grid{
          display:grid;
          grid-template-columns:1fr 1fr;
          gap:80px;
          align-items:center;
        }

        .about-image-wrap{
          position:relative;
        }

        .about-image{
          width:100%;
          height:540px;
          object-fit:cover;
          border-radius:25px;
          box-shadow:20px 25px 60px rgba(17,36,58,.13);
        }

        .about-card{
          position:absolute;
          right:-25px;
          bottom:30px;
          background:var(--navy);
          color:white;
          padding:25px;
          border-radius:20px;
          width:200px;
          text-align:center;
          box-shadow:0 20px 45px rgba(9,35,56,.25);
        }

        .about-card strong{
          display:block;
          font-family:Georgia,serif;
          font-size:39px;
          color:var(--gold2);
        }

        .about-card span{
          font-size:12px;
          color:#d5e0e7;
        }

        .about-copy h2{
          font-family:Georgia,serif;
          font-size:clamp(38px,5vw,56px);
          line-height:1.05;
          color:var(--navy);
          margin-bottom:22px;
        }

        .about-copy p{
          font-size:16px;
          line-height:1.85;
          color:var(--muted);
          margin-bottom:17px;
        }

        .values{
          display:grid;
          grid-template-columns:1fr 1fr;
          gap:15px;
          margin:28px 0;
        }

        .value{
          padding:17px;
          border:1px solid #e8decb;
          border-radius:15px;
          background:white;
        }

        .value strong{
          display:block;
          margin-bottom:5px;
          color:var(--navy);
        }

        .value span{
          font-size:12px;
          color:var(--muted);
        }

        .services-grid{
          display:grid;
          grid-template-columns:repeat(5,1fr);
          gap:16px;
        }

        .service{
          background:white;
          border:1px solid rgba(255,255,255,.15);
          border-radius:20px;
          padding:28px 20px;
          min-height:340px;
          transition:.35s;
          position:relative;
          overflow:hidden;
        }

        .service:before{
          content:"";
          position:absolute;
          width:100px;
          height:100px;
          border-radius:50%;
          background:rgba(200,144,50,.1);
          right:-40px;
          top:-40px;
        }

        .service:hover{
          transform:translateY(-9px);
          box-shadow:0 20px 45px rgba(0,0,0,.2);
        }

        .service-icon{
          width:58px;
          height:58px;
          border-radius:17px;
          display:grid;
          place-items:center;
          background:#fff1cf;
          color:var(--gold);
          margin-bottom:24px;
        }

        .service h3{
          font-family:Georgia,serif;
          font-size:21px;
          margin-bottom:13px;
          color:var(--navy);
        }

        .service p{
          color:#637181;
          font-size:13px;
          line-height:1.7;
          margin-bottom:20px;
        }

        .tags{
          display:flex;
          flex-wrap:wrap;
          gap:6px;
        }

        .tag{
          font-size:10px;
          border:1px solid #d9e2e8;
          border-radius:20px;
          padding:6px 8px;
          color:#60717f;
        }

        .why-grid{
          display:grid;
          grid-template-columns:1fr 1fr;
          gap:75px;
          align-items:center;
        }

        .why-copy h2{
          font-family:Georgia,serif;
          font-size:clamp(38px,5vw,56px);
          line-height:1.08;
          margin-bottom:20px;
        }

        .why-copy>p{
          line-height:1.8;
          color:#b9cad4;
          margin-bottom:25px;
        }

        .why-list{
          display:grid;
          gap:17px;
        }

        .why-item{
          display:flex;
          gap:15px;
          align-items:flex-start;
        }

        .why-check{
          width:35px;
          height:35px;
          min-width:35px;
          border-radius:50%;
          background:rgba(230,184,92,.15);
          color:var(--gold2);
          display:grid;
          place-items:center;
        }

        .why-item strong{
          display:block;
          margin-bottom:4px;
        }

        .why-item span{
          font-size:13px;
          line-height:1.5;
          color:#a9bdc9;
        }

        .why-photo{
          height:580px;
          object-fit:cover;
          width:100%;
          border-radius:30px;
          box-shadow:0 25px 60px rgba(0,0,0,.2);
        }

        .tech-wrap{
          display:flex;
          flex-wrap:wrap;
          justify-content:center;
          gap:12px;
          max-width:900px;
          margin:auto;
        }

        .tech{
          background:white;
          border:1px solid #e9e0d0;
          padding:17px 23px;
          border-radius:15px;
          display:flex;
          gap:10px;
          align-items:center;
          transition:.25s;
        }

        .tech:hover{
          transform:translateY(-4px);
          border-color:var(--gold);
        }

        .tech-dot{
          width:9px;
          height:9px;
          border-radius:50%;
          background:var(--gold);
        }

        .tech small{
          color:#85909b;
        }

        .process-grid{
          display:grid;
          grid-template-columns:repeat(6,1fr);
          gap:14px;
        }

        .process{
          position:relative;
          text-align:center;
        }

        .process:not(:last-child):after{
          content:"→";
          position:absolute;
          right:-13px;
          top:39px;
          color:var(--gold);
          font-size:20px;
        }

        .process-num{
          font-family:Georgia,serif;
          font-size:13px;
          color:var(--gold);
          margin-bottom:10px;
        }

        .process-icon{
          width:76px;
          height:76px;
          border-radius:50%;
          border:1px solid #e1c78d;
          background:#fff;
          margin:0 auto 18px;
          display:grid;
          place-items:center;
          color:var(--gold);
          box-shadow:0 12px 30px rgba(50,40,20,.07);
        }

        .process h3{
          font-family:Georgia,serif;
          margin-bottom:8px;
        }

        .process p{
          font-size:12px;
          line-height:1.6;
          color:var(--muted);
        }

        .stats{
          background:var(--navy);
          color:white;
          padding:70px 0;
        }

        .stats-grid{
          display:grid;
          grid-template-columns:repeat(4,1fr);
          gap:20px;
          text-align:center;
        }

        .stat{
          padding:20px;
          border-right:1px solid rgba(255,255,255,.15);
        }

        .stat:last-child{
          border:0;
        }

        .stat strong{
          font-family:Georgia,serif;
          font-size:50px;
          color:var(--gold2);
          display:block;
        }

        .stat span{
          font-size:13px;
          color:#bdcdd6;
        }

        .projects-grid{
          display:grid;
          grid-template-columns:repeat(3,1fr);
          gap:22px;
        }

        .project{
          background:white;
          border-radius:22px;
          overflow:hidden;
          box-shadow:0 10px 35px rgba(25,43,60,.08);
          transition:.35s;
        }

        .project:hover{
          transform:translateY(-8px);
          box-shadow:0 20px 50px rgba(25,43,60,.14);
        }

        .project-img{
          width:100%;
          height:250px;
          object-fit:cover;
          display:block;
        }

        .project-body{
          padding:25px;
        }

        .project-category{
          font-size:10px;
          color:var(--gold);
          font-weight:800;
          letter-spacing:2px;
          text-transform:uppercase;
        }

        .project h3{
          font-family:Georgia,serif;
          font-size:27px;
          margin:8px 0;
        }

        .project p{
          font-size:13px;
          line-height:1.7;
          color:var(--muted);
          margin-bottom:17px;
        }

        .project-link{
          border:0;
          background:none;
          color:var(--navy);
          font-weight:800;
          cursor:pointer;
          display:flex;
          align-items:center;
          gap:7px;
        }

        .testimonial-grid{
          display:grid;
          grid-template-columns:repeat(3,1fr);
          gap:22px;
        }

        .testimonial{
          background:white;
          border:1px solid #eee5d7;
          border-radius:22px;
          padding:30px;
        }

        .stars{
          color:var(--gold);
          display:flex;
          gap:2px;
          margin-bottom:20px;
        }

        .testimonial>p{
          font-family:Georgia,serif;
          font-size:18px;
          line-height:1.65;
          color:#33495b;
          margin-bottom:25px;
        }

        .person{
          display:flex;
          align-items:center;
          gap:13px;
        }

        .person img{
          width:52px;
          height:52px;
          border-radius:50%;
          object-fit:cover;
        }

        .person strong{
          display:block;
          color:var(--navy);
        }

        .person span{
          font-size:11px;
          color:var(--muted);
        }

        .faq-wrap{
          max-width:850px;
          margin:auto;
        }

        .faq{
          border-bottom:1px solid #e1d8ca;
        }

        .faq-question{
          width:100%;
          padding:24px 0;
          background:none;
          border:0;
          display:flex;
          justify-content:space-between;
          align-items:center;
          text-align:left;
          cursor:pointer;
          color:var(--navy);
          font-size:17px;
          font-weight:800;
        }

        .faq-answer{
          max-height:0;
          overflow:hidden;
          transition:.35s;
          color:var(--muted);
          line-height:1.8;
          font-size:14px;
        }

        .faq.open .faq-answer{
          max-height:200px;
          padding:0 40px 22px 0;
        }

        .faq-symbol{
          font-size:24px;
          color:var(--gold);
        }

        .contact-section{
          background:linear-gradient(135deg,#071f32,#123b52);
          color:white;
        }

        .contact-grid{
          display:grid;
          grid-template-columns:.85fr 1.15fr;
          gap:70px;
          align-items:start;
        }

        .contact-copy h2{
          font-family:Georgia,serif;
          font-size:clamp(40px,5vw,60px);
          line-height:1.05;
          margin-bottom:20px;
        }

        .contact-copy>p{
          color:#b8cad5;
          line-height:1.8;
          margin-bottom:30px;
        }

        .contact-details{
          display:grid;
          gap:18px;
        }

        .contact-detail{
          display:flex;
          align-items:center;
          gap:14px;
        }

        .contact-detail-icon{
          width:43px;
          height:43px;
          border-radius:13px;
          background:rgba(230,184,92,.13);
          color:var(--gold2);
          display:grid;
          place-items:center;
        }

        .contact-detail strong{
          display:block;
          font-size:13px;
          margin-bottom:3px;
        }

        .contact-detail span{
          font-size:12px;
          color:#adc0cb;
        }

        .contact-form{
          background:white;
          color:var(--navy);
          border-radius:25px;
          padding:35px;
          box-shadow:0 25px 60px rgba(0,0,0,.2);
        }

        .form-title{
          font-family:Georgia,serif;
          font-size:30px;
          margin-bottom:22px;
        }

        .form-grid{
          display:grid;
          grid-template-columns:1fr 1fr;
          gap:15px;
        }

        .field{
          margin-bottom:15px;
        }

        .field.full{
          grid-column:1/-1;
        }

        .field label{
          display:block;
          font-size:11px;
          font-weight:800;
          margin-bottom:7px;
          color:#556575;
        }

        .field input,
        .field textarea,
        .field select{
          width:100%;
          border:1px solid #e1e5e8;
          border-radius:12px;
          padding:14px;
          font-family:inherit;
          outline:none;
          background:#fbfcfd;
          transition:.2s;
        }

        .field textarea{
          min-height:120px;
          resize:vertical;
        }

        .field input:focus,
        .field textarea:focus,
        .field select:focus{
          border-color:var(--gold);
          box-shadow:0 0 0 3px rgba(200,144,50,.1);
        }

        .form-button{
          width:100%;
        }

        .footer{
          background:#061b2b;
          color:#b7c7d0;
          padding:60px 0 25px;
        }

        .footer-grid{
          display:grid;
          grid-template-columns:1.5fr 1fr 1fr 1fr;
          gap:40px;
          padding-bottom:45px;
        }

        .footer-description{
          font-size:13px;
          line-height:1.8;
          max-width:320px;
          margin-top:18px;
        }

        .footer h4{
          color:white;
          margin-bottom:18px;
          font-size:14px;
        }

        .footer-links{
          display:grid;
          gap:11px;
        }

        .footer-links button{
          background:none;
          border:0;
          color:#aebec8;
          text-align:left;
          cursor:pointer;
          font-size:12px;
        }

        .footer-links button:hover{
          color:var(--gold2);
        }

        .footer-bottom{
          border-top:1px solid rgba(255,255,255,.1);
          padding-top:23px;
          display:flex;
          justify-content:space-between;
          gap:20px;
          font-size:11px;
        }

        .socials{
          display:flex;
          gap:8px;
        }

        .social{
          width:34px;
          height:34px;
          border:1px solid #385263;
          border-radius:50%;
          display:grid;
          place-items:center;
          color:#c4d2d9;
          text-decoration:none;
        }

        .social:hover{
          background:var(--gold);
          color:var(--navy);
          border-color:var(--gold);
        }

        .traditional{
          position:absolute;
          opacity:.08;
          pointer-events:none;
          font-family:Georgia,serif;
          color:var(--gold);
          font-size:100px;
        }

        .t1{
          left:-25px;
          top:30px;
        }

        .t2{
          right:-25px;
          bottom:30px;
        }

        @media(max-width:1050px){
          .services-grid{
            grid-template-columns:repeat(3,1fr);
          }

          .process-grid{
            grid-template-columns:repeat(3,1fr);
            gap:35px;
          }

          .process:not(:last-child):after{
            display:none;
          }
        }

        @media(max-width:850px){
          .nav-links{
            position:absolute;
            top:78px;
            left:0;
            right:0;
            background:rgba(250,247,240,.98);
            padding:25px;
            display:none;
            flex-direction:column;
            align-items:stretch;
            gap:5px;
            box-shadow:0 20px 30px rgba(0,0,0,.08);
          }

          .nav-links.open{
            display:flex;
          }

          .nav-links button{
            text-align:center;
            padding:13px;
          }

          .navbar .btn{
            display:none;
          }

          .menu-btn{
            display:block;
          }

          .hero{
            padding-top:120px;
          }

          .hero-grid,
          .about-grid,
          .why-grid,
          .contact-grid{
            grid-template-columns:1fr;
            gap:45px;
          }

          .hero-visual{
            min-height:470px;
          }

          .hero-image{
            height:450px;
            width:370px;
          }

          .hero-badge.one{
            left:0;
          }

          .hero-badge.two{
            right:0;
          }

          .about-image{
            height:430px;
          }

          .why-photo{
            height:450px;
          }

          .projects-grid,
          .testimonial-grid{
            grid-template-columns:1fr;
          }

          .stats-grid{
            grid-template-columns:1fr 1fr;
          }

          .stat{
            border-right:0;
            border-bottom:1px solid rgba(255,255,255,.15);
          }

          .footer-grid{
            grid-template-columns:1fr 1fr;
          }

          .navbar .brand-logo{
            width:190px;
            height:62px;
          }
        }

        @media(max-width:600px){
          .section{
            padding:75px 0;
          }

          .hero h1{
            font-size:48px;
          }

          .hero-copy>p{
            font-size:15px;
          }

          .hero-visual{
            min-height:390px;
          }

          .hero-image{
            height:390px;
            width:285px;
          }

          .hero-badge{
            padding:12px;
          }

          .hero-badge.one{
            left:-5px;
            top:55px;
          }

          .hero-badge.two{
            right:-5px;
            bottom:30px;
          }

          .badge-icon{
            width:36px;
            height:36px;
          }

          .badge-text strong{
            font-size:12px;
          }

          .badge-text span{
            font-size:9px;
          }

          .services-grid{
            grid-template-columns:1fr;
          }

          .service{
            min-height:auto;
          }

          .values{
            grid-template-columns:1fr;
          }

          .process-grid{
            grid-template-columns:1fr 1fr;
          }

          .stats-grid{
            grid-template-columns:1fr 1fr;
          }

          .stat strong{
            font-size:38px;
          }

          .form-grid{
            grid-template-columns:1fr;
          }

          .field.full{
            grid-column:auto;
          }

          .footer-grid{
            grid-template-columns:1fr;
          }

          .footer-bottom{
            flex-direction:column;
          }

          .contact-form{
            padding:24px;
          }

          .navbar .brand-logo{
            width:165px;
            height:56px;
          }

          .footer .brand-logo{
            width:210px;
            height:70px;
          }
        }
      `}</style>

      <nav className={`navbar ${scrolled ? "scrolled" : ""}`}>
        <div className="container nav-inner">

          <div className="logo" onClick={() => scrollTo("home")}>
            <img
              className="brand-logo"
              src={logo}
              alt="Vighnex Technologies"
            />
          </div>

          <div className={`nav-links ${menuOpen ? "open" : ""}`}>
            {[
              "home",
              "about",
              "services",
              "why",
              "technology",
              "process",
              "projects",
              "testimonials",
              "faq",
              "contact",
            ].map((item) => (
              <button key={item} onClick={() => scrollTo(item)}>
                {item === "why"
                  ? "Why Us"
                  : item.charAt(0).toUpperCase() + item.slice(1)}
              </button>
            ))}
          </div>

          <button
            className="btn btn-primary"
            onClick={() => scrollTo("contact")}
          >
            Let's Connect
            <Icon type="arrow" size={17} />
          </button>

          <button
            className="menu-btn"
            onClick={() => setMenuOpen(!menuOpen)}
            aria-label="Toggle navigation"
          >
            <Icon type={menuOpen ? "close" : "menu"} size={28} />
          </button>
        </div>
      </nav>

      <section className="hero" id="home">
        <div className="container hero-grid">

          <div className="hero-copy">
            <div className="eyebrow">
              Traditional Values · Digital Future
            </div>

            <h1>
              Build Digital
              <br />
              <span>Possibilities.</span>
            </h1>

            <p>
              We transform ambitious ideas into meaningful digital experiences
              through technology, thoughtful design and strategies built for
              long-term growth.
            </p>

            <div className="hero-actions">
              <button
                className="btn btn-primary"
                onClick={() => scrollTo("contact")}
              >
                Start Your Journey
                <Icon type="arrow" size={17} />
              </button>

              <button
                className="btn"
                style={{
                  border: "1px solid #d7c9ae",
                  color: "var(--navy)",
                  background: "transparent",
                }}
                onClick={() => scrollTo("services")}
              >
                Explore Services
              </button>
            </div>

            <div className="hero-note">
              <Icon type="shield" size={19} />
              <span>
                <strong>Design-led.</strong> Engineering-driven.
                Growth-focused.
              </span>
            </div>
          </div>

          <div className="hero-visual">
            <div className="mandala"></div>

            <img
              className="hero-image"
              src="https://images.unsplash.com/photo-1551836022-d5d88e9218df?auto=format&fit=crop&w=900&q=85"
              alt="Vighnex Technologies digital solutions"
            />

            <div className="hero-badge one">
              <div className="badge-icon">
                <Icon type="spark" size={21} />
              </div>

              <div className="badge-text">
                <strong>Smart Solutions</strong>
                <span>Built around your goals</span>
              </div>
            </div>

            <div className="hero-badge two">
              <div className="badge-icon">
                <Icon type="rocket" size={21} />
              </div>

              <div className="badge-text">
                <strong>Digital Growth</strong>
                <span>From idea to impact</span>
              </div>
            </div>
          </div>
        </div>
      </section>

      <section className="section" id="about">
        <div className="container about-grid">

          <div className="about-image-wrap">
            <img
              className="about-image"
              src="https://images.unsplash.com/photo-1521737711867-e3b97375f902?auto=format&fit=crop&w=1000&q=85"
              alt="Professional team collaborating"
            />

            <div className="about-card">
              <strong>360°</strong>
              <span>
                Digital thinking from strategy to scale
              </span>
            </div>
          </div>

          <div className="about-copy">
            <div className="eyebrow">About Vighnex</div>

            <h2>
              Rooted in values. Driven by innovation.
            </h2>

            <p>
              Vighnex Technologies is a digital solutions company focused on
              creating technology that feels useful, intuitive and genuinely
              valuable.
            </p>

            <p>
              Our approach brings strategy, design, engineering and growth
              together so businesses do not have to manage disconnected digital
              partners.
            </p>

            <div className="values">

              <div className="value">
                <strong>Human First</strong>
                <span>
                  We design around real people and real problems.
                </span>
              </div>

              <div className="value">
                <strong>Quality Always</strong>
                <span>
                  Every detail matters from concept to deployment.
                </span>
              </div>

              <div className="value">
                <strong>Think Long Term</strong>
                <span>
                  We build foundations that can evolve with you.
                </span>
              </div>

              <div className="value">
                <strong>Move With Purpose</strong>
                <span>
                  Clear priorities create meaningful progress.
                </span>
              </div>

            </div>

            <button
              className="btn btn-primary"
              onClick={() => scrollTo("contact")}
            >
              Work With Us
              <Icon type="arrow" size={17} />
            </button>
          </div>
        </div>
      </section>

      <section className="section section-dark" id="services">

        <div className="traditional t1">✦</div>
        <div className="traditional t2">✧</div>

        <div className="container">

          <div className="section-title">
            <div className="eyebrow">What We Do</div>

            <h2>
              Complete digital solutions under one roof.
            </h2>

            <p>
              From your first sketch to your next million users, our
              capabilities are designed to work together.
            </p>
          </div>

          <div className="services-grid">
            {services.map((service) => (
              <div className="service" key={service.title}>

                <div className="service-icon">
                  <Icon type={service.icon} size={28} />
                </div>

                <h3>{service.title}</h3>

                <p>{service.text}</p>

                <div className="tags">
                  {service.tags.map((tag) => (
                    <span className="tag" key={tag}>
                      {tag}
                    </span>
                  ))}
                </div>

              </div>
            ))}
          </div>

        </div>
      </section>

      <section
        className="section section-dark"
        id="why"
        style={{ paddingTop: 90 }}
      >
        <div className="container why-grid">

          <div className="why-copy">

            <div className="eyebrow">
              Why Choose Us
            </div>

            <h2>
              Technology with a human touch.
            </h2>

            <p>
              Good technology should simplify complexity, not add to it. We
              combine strategic thinking, modern engineering and thoughtful
              communication to make digital projects easier to build and better
              to experience.
            </p>

            <div className="why-list">

              {[
                [
                  "Business Understanding",
                  "We start with your objectives instead of jumping directly into technology.",
                  "target",
                ],
                [
                  "Transparent Collaboration",
                  "Clear milestones, regular reviews and straightforward communication.",
                  "users",
                ],
                [
                  "Modern Engineering",
                  "Scalable architecture, clean development practices and performance-focused delivery.",
                  "code",
                ],
                [
                  "Security & Reliability",
                  "Security-conscious implementation and dependable digital foundations.",
                  "shield",
                ],
                [
                  "Growth Mindset",
                  "We design products that can improve continuously after launch.",
                  "spark",
                ],
              ].map((x) => (
                <div className="why-item" key={x[0]}>

                  <div className="why-check">
                    <Icon type={x[2]} size={18} />
                  </div>

                  <div>
                    <strong>{x[0]}</strong>
                    <span>{x[1]}</span>
                  </div>

                </div>
              ))}

            </div>
          </div>

          <img
            className="why-photo"
            src="https://images.unsplash.com/photo-1552664730-d307ca884978?auto=format&fit=crop&w=1100&q=85"
            alt="Business team meeting"
          />

        </div>
      </section>

      <section className="section" id="technology">

        <div className="container">

          <div className="section-title">
            <div className="eyebrow">
              Technology Stack
            </div>

            <h2>
              Built with technology that moves forward.
            </h2>

            <p>
              We choose tools based on the problem, not trends. Our stack
              supports fast development today and sustainable growth tomorrow.
            </p>
          </div>

          <div className="tech-wrap">
            {technologies.map((item) => (
              <div className="tech" key={item[0]}>
                <span className="tech-dot"></span>
                <strong>{item[0]}</strong>
                <small>{item[1]}</small>
              </div>
            ))}
          </div>

        </div>
      </section>

      <section
        className="section"
        id="process"
        style={{ background: "#f3ecdf" }}
      >

        <div className="container">

          <div className="section-title">

            <div className="eyebrow">
              Our Process
            </div>

            <h2>
              From first conversation to lasting impact.
            </h2>

            <p>
              A structured process keeps creativity focused, development
              predictable and every decision connected to your goals.
            </p>

          </div>

          <div className="process-grid">

            {process.map((item) => (
              <div className="process" key={item[1]}>

                <div className="process-num">
                  {item[0]}
                </div>

                <div className="process-icon">
                  <Icon type={item[3]} size={29} />
                </div>

                <h3>{item[1]}</h3>

                <p>{item[2]}</p>

              </div>
            ))}

          </div>

        </div>
      </section>

      <section className="stats">

        <div className="container stats-grid">

          <div className="stat">
            <strong>50+</strong>
            <span>Digital Ideas Transformed</span>
          </div>

          <div className="stat">
            <strong>100+</strong>
            <span>Projects & Deliverables</span>
          </div>

          <div className="stat">
            <strong>24/7</strong>
            <span>Digital Possibilities</span>
          </div>

          <div className="stat">
            <strong>100%</strong>
            <span>Commitment to Quality</span>
          </div>

        </div>
      </section>

      <section className="section" id="projects">

        <div className="container">

          <div className="section-title">

            <div className="eyebrow">
              Selected Work
            </div>

            <h2>
              Ideas become experiences.
            </h2>

            <p>
              A glimpse into the kind of digital experiences we love creating.
            </p>

          </div>

          <div className="projects-grid">

            {projects.map((project) => (
              <div className="project" key={project.title}>

                <img
                  className="project-img"
                  src={project.image}
                  alt={project.title}
                  loading="lazy"
                />

                <div className="project-body">

                  <div className="project-category">
                    {project.category}
                  </div>

                  <h3>{project.title}</h3>

                  <p>{project.text}</p>

                  <button
                    className="project-link"
                    onClick={() => scrollTo("contact")}
                  >
                    Discuss a Similar Project
                    <Icon type="arrow" size={15} />
                  </button>

                </div>
              </div>
            ))}

          </div>
        </div>
      </section>

      <section
        className="section"
        id="testimonials"
        style={{ background: "#f3ecdf" }}
      >

        <div className="container">

          <div className="section-title">

            <div className="eyebrow">
              Client Voices
            </div>

            <h2>
              Built on trust. Remembered for results.
            </h2>

            <p>
              Strong partnerships are at the center of everything we build.
            </p>

          </div>

          <div className="testimonial-grid">

            {testimonials.map((item) => (
              <div className="testimonial" key={item.name}>

                <div className="stars">
                  {[1, 2, 3, 4, 5].map((i) => (
                    <Icon key={i} type="star" size={15} />
                  ))}
                </div>

                <p>
                  “{item.text}”
                </p>

                <div className="person">

                  <img
                    src={item.image}
                    alt={item.name}
                    loading="lazy"
                  />

                  <div>
                    <strong>{item.name}</strong>
                    <span>{item.role}</span>
                  </div>

                </div>

              </div>
            ))}

          </div>
        </div>
      </section>

      <section className="section" id="faq">

        <div className="container">

          <div className="section-title">

            <div className="eyebrow">
              FAQ
            </div>

            <h2>
              Questions before we begin?
            </h2>

            <p>
              Here are answers to some of the things clients ask us most often.
            </p>

          </div>

          <div className="faq-wrap">

            {faqs.map((faq, index) => (
              <div
                className={`faq ${
                  activeFaq === index ? "open" : ""
                }`}
                key={faq[0]}
              >

                <button
                  className="faq-question"
                  onClick={() =>
                    setActiveFaq(
                      activeFaq === index ? -1 : index
                    )
                  }
                  aria-expanded={activeFaq === index}
                >
                  <span>{faq[0]}</span>

                  <span className="faq-symbol">
                    {activeFaq === index ? "−" : "+"}
                  </span>
                </button>

                <div className="faq-answer">
                  {faq[1]}
                </div>

              </div>
            ))}

          </div>
        </div>
      </section>

      <section className="section contact-section" id="contact">

        <div className="container contact-grid">

          <div className="contact-copy">

            <div className="eyebrow">
              Let's Connect
            </div>

            <h2>
              Have an idea? Let's make it real.
            </h2>

            <p>
              Tell us what you are building, what you want to improve or
              simply where you want to go next. We would love to hear the story
              behind your idea.
            </p>

            <div className="contact-details">

              <div className="contact-detail">

                <div className="contact-detail-icon">
                  <Icon type="phone" size={19} />
                </div>

                <div>
                  <strong>Call Us</strong>
                  <span>+91 98765 43210</span>
                </div>

              </div>

              <div className="contact-detail">

                <div className="contact-detail-icon">
                  <Icon type="mail" size={19} />
                </div>

                <div>
                  <strong>Email Us</strong>
                  <span>info@vighnex.com</span>
                </div>

              </div>

              <div className="contact-detail">

                <div className="contact-detail-icon">
                  <Icon type="location" size={19} />
                </div>

                <div>
                  <strong>Location</strong>
                  <span>Hyderabad, India</span>
                </div>

              </div>

            </div>
          </div>

          <form
            className="contact-form"
            onSubmit={(e) => {
              e.preventDefault();
              alert(
                "Thank you! Your enquiry has been received."
              );
            }}
          >

            <div className="form-title">
              Start a conversation
            </div>

            <div className="form-grid">

              <div className="field">
                <label>YOUR NAME</label>
                <input
                  type="text"
                  placeholder="Enter your name"
                  required
                />
              </div>

              <div className="field">
                <label>EMAIL ADDRESS</label>
                <input
                  type="email"
                  placeholder="you@example.com"
                  required
                />
              </div>

              <div className="field">
                <label>PHONE NUMBER</label>
                <input
                  type="tel"
                  placeholder="+91 XXXXX XXXXX"
                />
              </div>

              <div className="field">
                <label>SERVICE</label>

                <select defaultValue="">
                  <option value="" disabled>
                    Select a service
                  </option>
                  <option>Web Development</option>
                  <option>UI/UX Design</option>
                  <option>Digital Marketing</option>
                  <option>Mobile Development</option>
                  <option>Cloud Development</option>
                  <option>Complete Digital Solution</option>
                </select>

              </div>

              <div className="field full">

                <label>PROJECT DETAILS</label>

                <textarea
                  placeholder="Tell us a little about your idea, goals or requirements..."
                />

              </div>

            </div>

            <button
              className="btn btn-gold form-button"
              type="submit"
            >
              Send Enquiry
              <Icon type="arrow" size={17} />
            </button>

          </form>
        </div>
      </section>

      <footer className="footer">

        <div className="container">

          <div className="footer-grid">

            <div>

              <div
                className="logo"
                onClick={() => scrollTo("home")}
              >
                <img
                  className="brand-logo"
                  src={logo}
                  alt="Vighnex Technologies"
                />
              </div>

              <p className="footer-description">
                Building meaningful digital experiences where traditional
                values meet modern technology. Create. Build. Deploy. Grow.
              </p>

            </div>

            <div>

              <h4>Company</h4>

              <div className="footer-links">
                <button onClick={() => scrollTo("about")}>
                  About Us
                </button>

                <button onClick={() => scrollTo("why")}>
                  Why Choose Us
                </button>

                <button onClick={() => scrollTo("projects")}>
                  Our Work
                </button>

                <button onClick={() => scrollTo("contact")}>
                  Contact
                </button>
              </div>

            </div>

            <div>

              <h4>Services</h4>

              <div className="footer-links">

                <button onClick={() => scrollTo("services")}>
                  Web Development
                </button>

                <button onClick={() => scrollTo("services")}>
                  UI/UX Design
                </button>

                <button onClick={() => scrollTo("services")}>
                  Digital Marketing
                </button>

                <button onClick={() => scrollTo("services")}>
                  Mobile Development
                </button>

                <button onClick={() => scrollTo("services")}>
                  Cloud Development
                </button>

              </div>
            </div>

            <div>

              <h4>Let's Connect</h4>

              <div className="footer-links">

                <button onClick={() => scrollTo("contact")}>
                  Start a Project
                </button>

                <button onClick={() => scrollTo("faq")}>
                  FAQs
                </button>

                <button onClick={() => scrollTo("technology")}>
                  Technology
                </button>

                <button onClick={() => scrollTo("process")}>
                  Our Process
                </button>

              </div>
            </div>

          </div>

          <div className="footer-bottom">

            <span>
              © 2026 Vighnex Technologies. All Rights Reserved.
            </span>

            <div className="socials">

              <a
                className="social"
                href="https://www.linkedin.com"
                target="_blank"
                rel="noreferrer"
              >
                in
              </a>

              <a
                className="social"
                href="https://www.instagram.com"
                target="_blank"
                rel="noreferrer"
              >
                ◎
              </a>

              <a
                className="social"
                href="https://www.facebook.com"
                target="_blank"
                rel="noreferrer"
              >
                f
              </a>

              <a
                className="social"
                href="https://www.youtube.com"
                target="_blank"
                rel="noreferrer"
              >
                ▶
              </a>

            </div>
          </div>

        </div>
      </footer>
    </div>
  );
}
